<section class="card"><h2>Quiz and exam status</h2><p class="muted">This includes learners who took an assessment, are taking it, have not started, or missed the closing time.</p><div style="overflow-x:auto"><table><tr><th>Student</th><th>School ID</th><th>Assessment</th><th>Status</th><th>Best score</th></tr><?php foreach(($exam_results??[]) as $result): ?><tr><td><?=View::e($result['student_name'])?></td><td><?=View::e($result['id_number'])?></td><td><?=View::e($result['exam_title'])?></td><td><span class="badge"><?=View::e($result['status'])?></span></td><td><?=$result['score']===null?'—':View::e($result['score'].' / '.$result['max_score'].' ('.number_format((float)$result['percentage'],2).'%)')?></td></tr><?php endforeach; ?><?php if(empty($exam_results)): ?><tr><td colspan="5">No quizzes or exams have been posted for this course.</td></tr><?php endif; ?></table></div></section>
